<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { CalendarDays, Globe2, Heart, LibraryBig, Plus, RefreshCw, Search, SlidersHorizontal, Trash2, UsersRound } from "@lucide/vue";
import Button from "../components/ui/Button.vue";
import Badge from "../components/ui/Badge.vue";
import Input from "../components/ui/Input.vue";
import Select from "../components/ui/Select.vue";
import Textarea from "../components/ui/Textarea.vue";
import Modal from "../components/ui/Modal.vue";
import PageHeader from "../components/layout/PageHeader.vue";
import { useAppStore } from "../stores/app.js";
import { errorMessage, type ApiCharacter, type ApiEvent, type ApiRelationship, type ApiWorld, type ApiWorldLore } from "../types";
import type { CharacterRole, StoryMode, TriggerSource } from "@living-network/contracts";

type ModalKind = "world" | "character" | "relationship" | "event" | "lore" | null;
type RecurrenceKind = "ONCE" | "ANNUAL";
const store = useAppStore();
const worlds = ref<ApiWorld[]>([]);
const characters = ref<ApiCharacter[]>([]);
const relationships = ref<ApiRelationship[]>([]);
const events = ref<ApiEvent[]>([]);
const loreEntries = ref<ApiWorldLore[]>([]);
const activeWorldId = ref("");
const loreQuery = ref("");
const status = ref("正在加载内容设置");
const modalKind = ref<ModalKind>(null);
const editingId = ref<string | null>(null);
const saving = ref(false);
const worldForm = ref({ id: "", name: "", timezone: "Asia/Shanghai", storyMode: "DYNAMIC" as StoryMode, relationshipDynamicsEnabled: true });
const characterForm = ref({ id: "", displayName: "", role: "AI" as CharacterRole, timezone: "Asia/Shanghai", birthDate: "", personaPrompt: "", personaPromptRef: "", visualPromptRef: "" });
const relationForm = ref({ id: "", sourceCharacterId: "", targetCharacterId: "", relationshipType: "", affinity: 50 as number | string, trust: 50 as number | string, conflict: 0 as number | string, dependency: 0 as number | string, isPublic: true, isBidirectional: true });
const eventForm = ref({ id: "", eventKey: "", name: "", triggerSource: "MANUAL" as TriggerSource, recurrenceKind: "ONCE" as RecurrenceKind, runAt: "", month: 1 as number | string, day: 1 as number | string, localTime: "09:00", timezone: "Asia/Shanghai", targetCharacterId: "", recipientCharacterId: "", sendMessage: true, publishMoment: false, generateImage: false, enabled: true });
const loreForm = ref({ id: "", category: "世界设定", title: "", content: "", tags: "", isEnabled: true });
const selectedWorld = computed(() => worlds.value.find((world) => world.id === activeWorldId.value));
const modalTitle = computed(() => { const kind = modalKind.value; const label = kind === "world" ? "世界" : kind === "character" ? "角色" : kind === "relationship" ? "关系" : kind === "event" ? "事件" : kind === "lore" ? "世界设定" : "内容"; return label + (editingId.value ? "配置" : "新建"); });
const modalDescription = computed(() => { if (modalKind.value === "world") return "世界是角色、关系和事件的容器。"; if (modalKind.value === "character") return "角色人设会影响聊天、事件和视觉生成。"; if (modalKind.value === "relationship") return "这里填写的是关系初始状态，后续可被互动改变。"; if (modalKind.value === "event") return "事件定义角色何时产生什么行动。"; if (modalKind.value === "lore") return "世界设定会作为角色理解世界时的背景资料。"; return ""; });
function idFor(prefix: string) { return prefix + "-" + crypto.randomUUID(); }
function tags(value: string) { return [...new Set(value.split(",").map((tag) => tag.trim()).filter(Boolean))]; }
function characterName(id: string) { return characters.value.find((item) => item.id === id)?.displayName ?? "未选择角色"; }
function eventSummary(event: ApiEvent) { return (event.recurrence.kind === "ONCE" ? new Date(event.recurrence.runAt).toLocaleString() : "每年 " + event.recurrence.month + " 月 " + event.recurrence.day + " 日") + " · " + characterName(event.targetCharacterIds[0] ?? ""); }
function eventOutputs(event: ApiEvent) { return ["聊天", "动态", "图片"].filter((_, index) => [event.outputs.sendMessage, event.outputs.publishMoment, event.outputs.generateImage][index]).join(" · ") || "无输出"; }
async function load() {
  status.value = "正在读取内容...";
  try {
    worlds.value = (await store.api.getWorlds()).data ?? [];
    const world = worlds.value.find((item) => item.id === activeWorldId.value) ?? worlds.value.find((item) => item.id === store.currentWorldId) ?? worlds.value[0];
    activeWorldId.value = world?.id ?? ""; store.currentWorldId = activeWorldId.value;
    if (!world) { characters.value = []; relationships.value = []; events.value = []; loreEntries.value = []; status.value = "还没有故事世界"; return; }
    const [chars, edges, eventList, lore] = await Promise.all([store.api.getCharacters(world.id), store.api.getRelationships(world.id), store.api.getWorldEvents(world.id), store.api.getWorldLore(world.id)]);
    characters.value = chars.data ?? []; relationships.value = edges.data ?? []; events.value = eventList.data ?? []; loreEntries.value = lore.data ?? [];
    status.value = worlds.value.length + " 个世界 · " + characters.value.length + " 个角色 · " + events.value.length + " 个事件";
  } catch (error: unknown) { status.value = errorMessage(error); }
}
async function switchWorld() { store.currentWorldId = activeWorldId.value; await load(); }
function closeModal() { if (!saving.value) modalKind.value = null; }
function openWorld(world?: ApiWorld) { editingId.value = world?.id ?? null; worldForm.value = world ? { id: world.id, name: world.name, timezone: world.timezone, storyMode: world.storyMode, relationshipDynamicsEnabled: world.relationshipDynamicsEnabled } : { id: idFor("world"), name: "", timezone: "Asia/Shanghai", storyMode: "DYNAMIC", relationshipDynamicsEnabled: true }; modalKind.value = "world"; }
async function saveWorld() { saving.value = true; try { const body = { name: worldForm.value.name.trim(), timezone: worldForm.value.timezone.trim(), storyMode: worldForm.value.storyMode, relationshipDynamicsEnabled: worldForm.value.relationshipDynamicsEnabled }; if (editingId.value) await store.api.updateStoryWorld(editingId.value, body); else await store.api.createStoryWorld({ id: worldForm.value.id, ...body }); modalKind.value = null; await load(); } catch (error: unknown) { status.value = errorMessage(error); } finally { saving.value = false; } }
function openCharacter(character?: ApiCharacter) { editingId.value = character?.id ?? null; characterForm.value = character ? { id: character.id, displayName: character.displayName, role: character.role, timezone: character.timezone, birthDate: character.birthDate ?? "", personaPrompt: character.personaPrompt ?? "", personaPromptRef: character.personaPromptRef ?? "", visualPromptRef: character.visualPromptRef ?? "" } : { id: idFor("character"), displayName: "", role: "AI", timezone: selectedWorld.value?.timezone ?? "Asia/Shanghai", birthDate: "", personaPrompt: "", personaPromptRef: "", visualPromptRef: "" }; modalKind.value = "character"; }
async function saveCharacter() { if (!selectedWorld.value) return; saving.value = true; try { const optional = (value: string, key: string) => value.trim() ? { [key]: value.trim() } : {}; const body = { displayName: characterForm.value.displayName.trim(), timezone: characterForm.value.timezone.trim(), ...optional(characterForm.value.birthDate, "birthDate"), ...optional(characterForm.value.personaPrompt, "personaPrompt"), ...optional(characterForm.value.personaPromptRef, "personaPromptRef"), ...optional(characterForm.value.visualPromptRef, "visualPromptRef") }; if (editingId.value) await store.api.updateCharacter(editingId.value, body); else await store.api.createCharacter({ id: characterForm.value.id, role: characterForm.value.role, storyWorldId: selectedWorld.value.id, ...body }); modalKind.value = null; await load(); } catch (error: unknown) { status.value = errorMessage(error); } finally { saving.value = false; } }
function openRelation(edge?: ApiRelationship) { editingId.value = edge?.id ?? null; relationForm.value = edge ? { id: edge.id, sourceCharacterId: edge.sourceCharacterId, targetCharacterId: edge.targetCharacterId, relationshipType: edge.relationshipType, affinity: edge.initialState.affinity, trust: edge.initialState.trust, conflict: edge.initialState.conflict, dependency: edge.initialState.dependency, isPublic: edge.isPublic, isBidirectional: edge.isBidirectional } : { id: idFor("relationship"), sourceCharacterId: characters.value[0]?.id ?? "", targetCharacterId: characters.value[1]?.id ?? "", relationshipType: "", affinity: 50 as number | string, trust: 50 as number | string, conflict: 0 as number | string, dependency: 0 as number | string, isPublic: true, isBidirectional: true }; modalKind.value = "relationship"; }
async function saveRelation() { if (!selectedWorld.value) return; saving.value = true; try { const body = { relationshipType: relationForm.value.relationshipType.trim(), initialState: { affinity: Number(relationForm.value.affinity), trust: Number(relationForm.value.trust), conflict: Number(relationForm.value.conflict), dependency: Number(relationForm.value.dependency) }, isPublic: relationForm.value.isPublic, isBidirectional: relationForm.value.isBidirectional }; if (editingId.value) await store.api.updateRelationship(editingId.value, body); else await store.api.createRelationship({ id: relationForm.value.id, storyWorldId: selectedWorld.value.id, sourceCharacterId: relationForm.value.sourceCharacterId, targetCharacterId: relationForm.value.targetCharacterId, ...body }); modalKind.value = null; await load(); } catch (error: unknown) { status.value = errorMessage(error); } finally { saving.value = false; } }
function openEvent(event?: ApiEvent) { editingId.value = event?.id ?? null; eventForm.value = event ? { id: event.id, eventKey: event.eventKey, name: event.name, triggerSource: event.triggerSource, recurrenceKind: event.recurrence.kind, runAt: event.recurrence.kind === "ONCE" ? event.recurrence.runAt.slice(0, 16) : "", month: event.recurrence.kind === "ANNUAL" ? event.recurrence.month : 1, day: event.recurrence.kind === "ANNUAL" ? event.recurrence.day : 1, localTime: event.recurrence.kind === "ANNUAL" ? event.recurrence.localTime : "09:00", timezone: event.timezone, targetCharacterId: event.targetCharacterIds[0] ?? "", recipientCharacterId: event.recipientCharacterIds[0] ?? "", sendMessage: event.outputs.sendMessage, publishMoment: event.outputs.publishMoment, generateImage: event.outputs.generateImage, enabled: event.enabled } : { id: idFor("event"), eventKey: "", name: "", triggerSource: "MANUAL", recurrenceKind: "ONCE", runAt: new Date(Date.now() + 3600000).toISOString().slice(0, 16), month: 1 as number | string, day: 1 as number | string, localTime: "09:00", timezone: selectedWorld.value?.timezone ?? "Asia/Shanghai", targetCharacterId: characters.value[0]?.id ?? "", recipientCharacterId: characters.value[0]?.id ?? "", sendMessage: true, publishMoment: false, generateImage: false, enabled: true }; modalKind.value = "event"; }
async function saveEvent() { if (!selectedWorld.value) return; saving.value = true; try { const recurrence = eventForm.value.recurrenceKind === "ONCE" ? { kind: "ONCE" as const, runAt: new Date(eventForm.value.runAt).toISOString() } : { kind: "ANNUAL" as const, month: Number(eventForm.value.month), day: Number(eventForm.value.day), localTime: eventForm.value.localTime }; const body = { eventKey: eventForm.value.eventKey.trim(), name: eventForm.value.name.trim(), triggerSource: eventForm.value.triggerSource, timezone: eventForm.value.timezone.trim(), recurrence, targetCharacterIds: [eventForm.value.targetCharacterId], recipientCharacterIds: [eventForm.value.recipientCharacterId], outputs: { sendMessage: eventForm.value.sendMessage, publishMoment: eventForm.value.publishMoment, generateImage: eventForm.value.generateImage }, enabled: eventForm.value.enabled }; if (editingId.value) await store.api.updateWorldEvent(editingId.value, body); else await store.api.createWorldEvent({ id: eventForm.value.id, storyWorldId: selectedWorld.value.id, ...body, createdAt: new Date().toISOString() }); modalKind.value = null; await load(); } catch (error: unknown) { status.value = errorMessage(error); } finally { saving.value = false; } }
function openLore(entry?: ApiWorldLore) { editingId.value = entry?.id ?? null; loreForm.value = entry ? { id: entry.id, category: entry.category, title: entry.title, content: entry.content, tags: entry.tags.join(", "), isEnabled: entry.isEnabled } : { id: idFor("lore"), category: "世界设定", title: "", content: "", tags: "", isEnabled: true }; modalKind.value = "lore"; }
async function saveLore() { if (!selectedWorld.value) return; saving.value = true; try { const body = { category: loreForm.value.category.trim(), title: loreForm.value.title.trim(), content: loreForm.value.content.trim(), tags: tags(loreForm.value.tags), isEnabled: loreForm.value.isEnabled }; if (editingId.value) await store.api.updateWorldLore(editingId.value, body); else await store.api.createWorldLore({ id: loreForm.value.id, storyWorldId: selectedWorld.value.id, ...body }); modalKind.value = null; await load(); } catch (error: unknown) { status.value = errorMessage(error); } finally { saving.value = false; } }
async function deleteLore(entry: ApiWorldLore) { if (!window.confirm("确定删除这条世界设定吗？")) return; try { await store.api.deleteWorldLore(entry.id); await load(); } catch (error: unknown) { status.value = errorMessage(error); } }
onMounted(load);
</script>
<template>
<section class="page">
<PageHeader eyebrow="世界资料库" title="内容管理" description="摘要卡片只展示关键结果，具体字段通过配置弹窗编辑。" :status="status"><template #actions><Select v-model="activeWorldId" aria-label="当前内容世界" @update:model-value="switchWorld"><option value="" disabled>选择当前世界</option><option v-for="world in worlds" :key="world.id" :value="world.id">{{ world.name }}</option></Select><Button variant="secondary" @click="load"><RefreshCw :size="15" />刷新</Button></template></PageHeader>
<section v-if="selectedWorld" class="world-context"><div><p class="context-eyebrow">当前世界</p><h2>{{ selectedWorld.name }}</h2><p>{{ selectedWorld.storyMode === "DYNAMIC" ? "动态世界：关系和事件可以持续变化。" : "静态世界：关系以设定值为准。" }} · {{ selectedWorld.timezone }}</p></div><Button variant="secondary" size="sm" @click="openWorld(selectedWorld)"><SlidersHorizontal :size="15" />配置世界</Button></section>
<div class="content-grid">
<section class="content-card list-card"><header class="content-card-header"><div class="section-mark"><Globe2 :size="17" /></div><div><h2>故事世界</h2><p>世界名称、时区和关系变化规则。</p></div><Button variant="secondary" size="sm" @click="openWorld()"><Plus :size="15" />新建</Button></header><div class="summary-list"><article v-for="world in worlds" :key="world.id" class="summary-item" :class="{ selected: world.id === activeWorldId }"><div><strong>{{ world.name }}</strong><small>{{ world.storyMode === "DYNAMIC" ? "动态世界" : "静态世界" }} · {{ world.timezone }}</small></div><div class="summary-actions"><Badge :tone="world.id === activeWorldId ? 'success' : 'neutral'">{{ world.id === activeWorldId ? "当前" : "可切换" }}</Badge><Button variant="ghost" size="icon" :aria-label="'配置 ' + world.name" :title="'配置 ' + world.name" @click="openWorld(world)"><SlidersHorizontal :size="16" /></Button></div></article></div></section>
<section class="content-card list-card"><header class="content-card-header"><div class="section-mark"><UsersRound :size="17" /></div><div><h2>角色档案</h2><p>角色身份、时区和人设提示。</p></div><Button variant="secondary" size="sm" :disabled="!selectedWorld" @click="openCharacter()"><Plus :size="15" />新建</Button></header><div class="summary-list"><article v-for="character in characters" :key="character.id" class="summary-item"><div><strong>{{ character.displayName }}</strong><small>{{ character.role === "AI" ? "AI 角色" : "体验者角色" }} · {{ character.timezone }}</small></div><div class="summary-actions"><Badge :tone="character.personaPrompt ? 'info' : 'warning'">{{ character.personaPrompt ? "已有人设" : "待补人设" }}</Badge><Button variant="ghost" size="icon" :aria-label="'配置 ' + character.displayName" :title="'配置 ' + character.displayName" @click="openCharacter(character)"><SlidersHorizontal :size="16" /></Button></div></article><p v-if="!characters.length" class="empty-copy">当前世界还没有角色。</p></div></section>
<section class="content-card list-card"><header class="content-card-header"><div class="section-mark"><Heart :size="17" /></div><div><h2>关系设定</h2><p>角色之间的关系类型和初始状态。</p></div><Button variant="secondary" size="sm" :disabled="characters.length < 2" @click="openRelation()"><Plus :size="15" />新建</Button></header><div class="summary-list"><article v-for="edge in relationships" :key="edge.id" class="summary-item"><div><strong>{{ characterName(edge.sourceCharacterId) }} ↔ {{ characterName(edge.targetCharacterId) }}</strong><small>{{ edge.relationshipType }} · 好感 {{ edge.initialState.affinity }} · 信任 {{ edge.initialState.trust }}</small></div><div class="summary-actions"><Badge :tone="edge.isPublic ? 'info' : 'neutral'">{{ edge.isPublic ? "公开" : "私密" }}</Badge><Button variant="ghost" size="icon" aria-label="配置关系" title="配置关系" @click="openRelation(edge)"><SlidersHorizontal :size="16" /></Button></div></article><p v-if="!relationships.length" class="empty-copy">还没有关系设定。</p></div></section>
<section class="content-card list-card"><header class="content-card-header"><div class="section-mark"><CalendarDays :size="17" /></div><div><h2>事件安排</h2><p>触发条件、参与角色和输出方式。</p></div><Button variant="secondary" size="sm" :disabled="!characters.length" @click="openEvent()"><Plus :size="15" />新建</Button></header><div class="summary-list"><article v-for="event in events" :key="event.id" class="summary-item"><div><strong>{{ event.name }}</strong><small>{{ eventSummary(event) }} · {{ eventOutputs(event) }}</small></div><div class="summary-actions"><Badge :tone="event.enabled ? 'success' : 'neutral'">{{ event.enabled ? "已启用" : "已停用" }}</Badge><Button variant="ghost" size="icon" aria-label="配置事件" title="配置事件" @click="openEvent(event)"><SlidersHorizontal :size="16" /></Button></div></article><p v-if="!events.length" class="empty-copy">还没有事件安排。</p></div></section>
<section class="content-card list-card lore-card"><header class="content-card-header"><div class="section-mark"><LibraryBig :size="17" /></div><div><h2>世界设定</h2><p>地点、事实、术语和背景资料。</p></div><Button variant="secondary" size="sm" :disabled="!selectedWorld" @click="openLore()"><Plus :size="15" />新建</Button></header><div class="lore-toolbar"><Input v-model="loreQuery" placeholder="搜索标题、正文或标签" aria-label="搜索世界设定" @keyup.enter="load" /><Button variant="secondary" size="sm" aria-label="搜索世界设定" title="搜索世界设定" @click="load"><Search :size="15" />搜索</Button></div><div class="summary-list"><article v-for="entry in loreEntries" :key="entry.id" class="summary-item"><div><strong>{{ entry.title }}</strong><small>{{ entry.category }} · {{ entry.tags.length ? entry.tags.join("、") : "未添加标签" }}</small></div><div class="summary-actions"><Badge :tone="entry.isEnabled ? 'success' : 'neutral'">{{ entry.isEnabled ? "已启用" : "已停用" }}</Badge><Button variant="ghost" size="icon" aria-label="编辑世界设定" title="编辑世界设定" @click="openLore(entry)"><SlidersHorizontal :size="16" /></Button><Button variant="ghost" size="icon" aria-label="删除世界设定" title="删除世界设定" @click="deleteLore(entry)"><Trash2 :size="16" /></Button></div></article><p v-if="!loreEntries.length" class="empty-copy">没有匹配的世界设定。</p></div></section>
</div>
<Modal :open="modalKind === 'world'" :title="modalTitle" :description="modalDescription" @close="closeModal"><form id="world-form" class="modal-form" @submit.prevent="saveWorld"><label class="field-group"><span>世界名称<small>玩家和角色看到的名字。</small></span><Input v-model="worldForm.name" placeholder="例如：潮汐城" required /></label><label class="field-group"><span>世界模式<small>动态世界允许关系和事件继续变化。</small></span><Select v-model="worldForm.storyMode" aria-label="世界模式"><option value="DYNAMIC">动态世界</option><option value="STATIC">静态世界</option></Select></label><label class="field-group"><span>世界时区<small>事件排期按照这里解释。</small></span><Input v-model="worldForm.timezone" placeholder="例如：Asia/Shanghai" required /></label><label class="check-row"><input v-model="worldForm.relationshipDynamicsEnabled" type="checkbox" />启用关系变化</label></form><template #footer><Button type="button" variant="ghost" @click="closeModal">取消</Button><Button type="submit" form="world-form" :loading="saving">保存世界</Button></template></Modal>
<Modal :open="modalKind === 'character'" :title="modalTitle" :description="modalDescription" @close="closeModal"><form id="character-form" class="modal-form" @submit.prevent="saveCharacter"><label class="field-group"><span>显示名称<small>聊天、动态和事件中使用的名字。</small></span><Input v-model="characterForm.displayName" placeholder="例如：林遥" required /></label><label class="field-group"><span>角色类型<small>AI 角色由模型驱动；体验者角色代表玩家。</small></span><Select v-model="characterForm.role" aria-label="角色类型" :disabled="!!editingId"><option value="AI">AI 角色</option><option value="USER">体验者角色</option></Select></label><label class="field-group"><span>角色时区<small>生日和日程按这里解释。</small></span><Input v-model="characterForm.timezone" placeholder="例如：Asia/Shanghai" required /></label><label class="field-group"><span>生日（可选）<small>用于生日类事件匹配。</small></span><Input v-model="characterForm.birthDate" type="date" aria-label="生日" /></label><label class="field-group"><span>角色人设<small>描述性格、说话方式、经历和边界。</small></span><Textarea v-model="characterForm.personaPrompt" :rows="6" placeholder="例如：她谨慎、观察力强，不会直接说出未确认的猜测。" /></label><details class="advanced-fields"><summary>高级引用（可选）</summary><label class="field-group"><span>人设引用地址<small>例如 persona://lin-yao。</small></span><Input v-model="characterForm.personaPromptRef" placeholder="persona://..." /></label><label class="field-group"><span>视觉提示词引用<small>例如 visual://lin-yao。</small></span><Input v-model="characterForm.visualPromptRef" placeholder="visual://lin-yao" /></label></details></form><template #footer><Button type="button" variant="ghost" @click="closeModal">取消</Button><Button type="submit" form="character-form" :loading="saving">保存角色</Button></template></Modal>
<Modal :open="modalKind === 'relationship'" :title="modalTitle" :description="modalDescription" @close="closeModal"><form id="relationship-form" class="modal-form" @submit.prevent="saveRelation"><div class="field-grid"><label class="field-group"><span>关系发起者<small>关系从谁的视角建立。</small></span><Select v-model="relationForm.sourceCharacterId" aria-label="关系发起者" :disabled="!!editingId"><option v-for="character in characters" :key="character.id + '-source'" :value="character.id">{{ character.displayName }}</option></Select></label><label class="field-group"><span>关系对象<small>关系指向的另一个角色。</small></span><Select v-model="relationForm.targetCharacterId" aria-label="关系对象" :disabled="!!editingId"><option v-for="character in characters" :key="character.id + '-target'" :value="character.id">{{ character.displayName }}</option></Select></label></div><label class="field-group"><span>关系类型<small>例如“旧友”“同事”或“竞争对手”。</small></span><Input v-model="relationForm.relationshipType" placeholder="例如：旧友" required /></label><div class="field-grid four-fields"><label class="field-group"><span>好感<small>0-100</small></span><Input v-model="relationForm.affinity" type="number" min="0" max="100" aria-label="好感" /></label><label class="field-group"><span>信任<small>0-100</small></span><Input v-model="relationForm.trust" type="number" min="0" max="100" aria-label="信任" /></label><label class="field-group"><span>冲突<small>0-100</small></span><Input v-model="relationForm.conflict" type="number" min="0" max="100" aria-label="冲突" /></label><label class="field-group"><span>依赖<small>0-100</small></span><Input v-model="relationForm.dependency" type="number" min="0" max="100" aria-label="依赖" /></label></div><label class="check-row"><input v-model="relationForm.isPublic" type="checkbox" />对玩家可见</label><label class="check-row"><input v-model="relationForm.isBidirectional" type="checkbox" />视为双向关系</label></form><template #footer><Button type="button" variant="ghost" @click="closeModal">取消</Button><Button type="submit" form="relationship-form" :loading="saving">保存关系</Button></template></Modal>
<Modal :open="modalKind === 'event'" :title="modalTitle" :description="modalDescription" @close="closeModal"><form id="event-form" class="modal-form" @submit.prevent="saveEvent"><label class="field-group"><span>事件标识 Key<small>系统内部唯一标识，建议用英文、数字和短横线。</small></span><Input v-model="eventForm.eventKey" placeholder="例如：lin-yao-birthday" required /></label><label class="field-group"><span>事件名称<small>创作中心和日历中显示的名称。</small></span><Input v-model="eventForm.name" placeholder="例如：林遥的生日" required /></label><div class="field-grid"><label class="field-group"><span>触发来源<small>决定事件由什么机制触发。</small></span><Select v-model="eventForm.triggerSource" aria-label="触发来源"><option value="MANUAL">手动触发</option><option value="WORLD_HOLIDAY">世界节日</option><option value="STORY_NODE">剧情节点</option><option value="BIRTHDAY">生日</option><option value="USER_INTERACTION">玩家互动</option><option value="RELATIONSHIP_EVENT">关系事件</option></Select></label><label class="field-group"><span>事件时区<small>排期时间按照这里解释。</small></span><Input v-model="eventForm.timezone" placeholder="例如：Asia/Shanghai" required /></label></div><label class="field-group"><span>重复方式<small>一次性事件只执行指定时间；年度事件每年重复。</small></span><Select v-model="eventForm.recurrenceKind" aria-label="重复方式"><option value="ONCE">一次性</option><option value="ANNUAL">每年重复</option></Select></label><label v-if="eventForm.recurrenceKind === 'ONCE'" class="field-group"><span>执行时间<small>保存后转换为事件时区。</small></span><Input v-model="eventForm.runAt" type="datetime-local" required /></label><div v-else class="field-grid"><label class="field-group"><span>月份<small>1-12</small></span><Input v-model="eventForm.month" type="number" min="1" max="12" aria-label="事件月份" /></label><label class="field-group"><span>日期<small>1-31</small></span><Input v-model="eventForm.day" type="number" min="1" max="31" aria-label="事件日期" /></label><label class="field-group"><span>本地时间<small>例如 09:00</small></span><Input v-model="eventForm.localTime" type="time" aria-label="事件本地时间" /></label></div><div class="field-grid"><label class="field-group"><span>行动角色<small>事件由谁产生行动。</small></span><Select v-model="eventForm.targetCharacterId" aria-label="行动角色" required><option v-for="character in characters" :key="character.id + '-event-target'" :value="character.id">{{ character.displayName }}</option></Select></label><label class="field-group"><span>接收角色<small>消息或关系变化发给谁。</small></span><Select v-model="eventForm.recipientCharacterId" aria-label="接收角色" required><option v-for="character in characters" :key="character.id + '-event-recipient'" :value="character.id">{{ character.displayName }}</option></Select></label></div><div class="output-options"><span class="field-label">事件输出<small>事件完成后产生的结果。</small></span><label class="check-row"><input v-model="eventForm.sendMessage" type="checkbox" />发送聊天消息</label><label class="check-row"><input v-model="eventForm.publishMoment" type="checkbox" />发布动态</label><label class="check-row"><input v-model="eventForm.generateImage" type="checkbox" />生成图片</label></div><label class="check-row"><input v-model="eventForm.enabled" type="checkbox" />启用这个事件</label></form><template #footer><Button type="button" variant="ghost" @click="closeModal">取消</Button><Button type="submit" form="event-form" :loading="saving">保存事件</Button></template></Modal>
<Modal :open="modalKind === 'lore'" :title="modalTitle" :description="modalDescription" @close="closeModal"><form id="lore-form" class="modal-form" @submit.prevent="saveLore"><label class="field-group"><span>分类<small>例如“地点”“人物”“规则”或“术语”。</small></span><Input v-model="loreForm.category" placeholder="例如：地点" required /></label><label class="field-group"><span>标题<small>列表和搜索结果中显示的名称。</small></span><Input v-model="loreForm.title" placeholder="例如：潮汐城的旧港" required /></label><label class="field-group"><span>设定正文<small>角色和事件生成器读取的事实、背景或规则。</small></span><Textarea v-model="loreForm.content" :rows="8" placeholder="例如：旧港每天在退潮后开放四小时。" required /></label><label class="field-group"><span>标签<small>用逗号分隔，方便搜索。</small></span><Input v-model="loreForm.tags" placeholder="例如：地点,港口,潮汐" /></label><label class="check-row"><input v-model="loreForm.isEnabled" type="checkbox" />让生成器使用这条设定</label></form><template #footer><Button type="button" variant="ghost" @click="closeModal">取消</Button><Button type="submit" form="lore-form" :loading="saving">保存设定</Button></template></Modal>
</section>
</template>
